mapper.select:
SELECT c.*
FROM sys_flow_node_config c
WHERE c.id = #{id}
  AND c.tenant_id = #{tenantId}
  AND c.del_flag = '0'
LIMIT 1

mapper.update:
UPDATE sys_flow_node_config
SET del_flag = id,
    update_time = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND del_flag = '0'
